import { useState, useMemo, useEffect, useRef } from 'react';
import { useOutletContext } from 'react-router-dom';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { Input } from '@/components/ui/input';
import {
  Sparkles,
  Calendar,
  Wand2,
  Lightbulb,
  AlertTriangle,
   ChevronRight,
   ChevronDown,
  FileText,
  Image as ImageIcon,
  Video,
  Mic,
  User,
  Code,
  Palette,
  Briefcase,
  Globe,
  Bot,
  Search,
  X,
  ListChecks,
} from 'lucide-react';
import {
  MOCK_AI_TIP_GROUPS,
  AI_TIP_CATEGORIES,
  AI_MANJU_FEATURED,
  type IAITip,
  type AITipCategory,
} from '@/data/ai-tips';
import { formatDateCN } from '@/lib/date-utils';
import { ensureArray } from '@/lib/utils';
import type { ThemeConfig, FestivalBadge } from '@/lib/theme';
import NotePadSection, { type NoteItem } from '@/components/NotePadSection';
import { toast } from 'sonner';
import RichTipText from '@/components/RichTipText';
import CollapsibleSection from '@/components/CollapsibleSection';
import { NotebookPen } from 'lucide-react';

// 分类图标映射
const categoryIconMap: Record<AITipCategory, typeof FileText> = {
  全部: Lightbulb,
  AI文案: FileText,
  AI生图: ImageIcon,
  AI视频: Video,
  AI配音: Mic,
  AI数字人: User,
  AI编程: Code,
  AI漫剧: Palette,
  AI办公: Briefcase,
  AI跨境: Globe,
  '智能体/Skill': Bot,
};

const categoryColorMap: Record<string, { bg: string; text: string; border: string }> = {
  AI文案: { bg: 'bg-blue-50', text: 'text-blue-600', border: 'border-blue-100' },
  AI生图: { bg: 'bg-purple-50', text: 'text-purple-600', border: 'border-purple-100' },
  AI视频: { bg: 'bg-pink-50', text: 'text-pink-600', border: 'border-pink-100' },
  AI配音: { bg: 'bg-orange-50', text: 'text-orange-600', border: 'border-orange-100' },
  AI数字人: { bg: 'bg-rose-50', text: 'text-rose-600', border: 'border-rose-100' },
  AI编程: { bg: 'bg-indigo-50', text: 'text-indigo-600', border: 'border-indigo-100' },
  AI漫剧: { bg: 'bg-emerald-50', text: 'text-emerald-600', border: 'border-emerald-100' },
  AI办公: { bg: 'bg-amber-50', text: 'text-amber-600', border: 'border-amber-100' },
  AI跨境: { bg: 'bg-teal-50', text: 'text-teal-600', border: 'border-teal-100' },
  '智能体/Skill': { bg: 'bg-cyan-50', text: 'text-cyan-600', border: 'border-cyan-100' },
};

export default function AILearningPage() {
  const { theme } = useOutletContext<{ theme: ThemeConfig; festival: FestivalBadge }>();
  const [activeCat, setActiveCat] = useState<AITipCategory>('全部');
  const [keyword, setKeyword] = useState('');
  const today = useMemo(() => new Date(), []);
  const [aiNotes, setAiNotes] = useState<NoteItem[]>([]);

  // ===== 页内锚点导航 =====
  const anchorRefs = useRef<Record<string, HTMLElement | null>>({
    manju: null,
    tips: null,
    notes: null,
  });
  const [activeAnchor, setActiveAnchor] = useState('manju');

  function scrollToAnchor(key: string) {
    const el = anchorRefs.current[key];
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }

  // 滚动时高亮当前锚点
  useEffect(() => {
    const mainEl = document.querySelector('main');
    if (!mainEl) return;
    function handleScroll() {
      const scrollTop = mainEl.scrollTop;
      const offsets = Object.entries(anchorRefs.current)
        .filter(([, el]) => el !== null)
        .map(([key, el]) => ({
          key,
          top: el!.getBoundingClientRect().top + scrollTop - 120,
        }))
        .sort((a, b) => a.top - b.top);
      let current = offsets[0]?.key || 'manju';
      for (const o of offsets) {
        if (scrollTop >= o.top) current = o.key;
      }
      setActiveAnchor(current);
    }
    mainEl.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll();
    return () => mainEl.removeEventListener('scroll', handleScroll);
  }, []);

  // AI漫剧10步手风琴：默认展开第1步
  const [manjuExpandedStep, setManjuExpandedStep] = useState<number>(0);

  function toggleManjuStep(idx: number) {
    setManjuExpandedStep(prev => prev === idx ? -1 : idx);
  }

  // 技巧卡片展开状态（卡片内手风琴，与板块手风琴相互独立）
  const [expandedTipId, setExpandedTipId] = useState<string | null>(null);

  // 板块手风琴：同一时刻只展开一个板块，默认全部折叠
  const [expandedId, setExpandedId] = useState<string>('hero');
  function toggleSection(id: string) {
    setExpandedId(prev => (prev === id ? '' : id));
  }

  // 每日推荐：10个分类各保底至少1条 + 额外2~5条随机分配 + 分类内按天轮转
  // 每天总数 12~15 条浮动，任何分类都不为0
  const dailyTips = useMemo(() => {
    const allTips = MOCK_AI_TIP_GROUPS.flat();
    // 按分类分组（保持 AI_TIP_CATEGORIES 顺序，去掉「全部」）
    const categoryList = AI_TIP_CATEGORIES.filter(c => c !== '全部');
    const byCategory: Record<string, IAITip[]> = {};
    allTips.forEach(t => {
      if (!byCategory[t.category]) byCategory[t.category] = [];
      byCategory[t.category].push(t);
    });
    // 有效日期（8点前显示前一天的）
    const d = new Date(today);
    if (d.getHours() < 8) d.setDate(d.getDate() - 1);
    const dayOfYear = Math.floor((d.getTime() - new Date(d.getFullYear(), 0, 0).getTime()) / 86400000);

    const result: IAITip[] = [];
    const usedIndices: Record<string, number[]> = {};

    // 保底1：每个分类各取1条，分类内按天轮转偏移
    categoryList.forEach((cat, ci) => {
      const arr = byCategory[cat];
      if (!arr || arr.length === 0) return;
      // 每个分类用不同的偏移基数，保证不同分类轮转错位
      const idx = (dayOfYear + ci * 37) % arr.length;
      result.push(arr[idx]);
      usedIndices[cat] = [idx];
    });

    // 种子随机数发生器（同一天结果稳定）
    let seed = (dayOfYear * 1103515245 + 12345) & 0x7fffffff;
    const rand = () => {
      seed = (seed * 1103515245 + 12345) & 0x7fffffff;
      return seed / 0x7fffffff;
    };

    // 额外 2~5 条，随机分配到各分类（从该分类取下一条未取过的）
    const extraCount = 2 + (dayOfYear % 4); // 结果 2,3,4,5
    for (let i = 0; i < extraCount; i++) {
      const candidates = categoryList.filter(cat => {
        const arr = byCategory[cat];
        if (!arr) return false;
        const used = usedIndices[cat]?.length || 0;
        return used < arr.length;
      });
      if (candidates.length === 0) break;

      const cat = candidates[Math.floor(rand() * candidates.length)];
      const arr = byCategory[cat];
      const usedIdx = usedIndices[cat];

      // 沿轮转方向取下一条未用过的
      let nextIdx = -1;
      for (let j = 1; j <= arr.length; j++) {
        const candidateIdx = ((dayOfYear + categoryList.indexOf(cat) * 37) + j) % arr.length;
        if (!usedIdx.includes(candidateIdx)) {
          nextIdx = candidateIdx;
          break;
        }
      }
      if (nextIdx === -1) continue;

      result.push(arr[nextIdx]);
      usedIdx.push(nextIdx);
    }

    // 按天打散顺序，避免同一天分类顺序固定
    const shuffled = [...result];
    let s = dayOfYear * 2654435761;
    const rand2 = () => {
      s = (s * 1664525 + 1013904223) & 0xffffffff;
      return (s >>> 0) / 0xffffffff;
    };
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(rand2() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }

    return shuffled;
  }, [today]);

  // 所有技巧（用于全局搜索）
  const allTips = useMemo(() => MOCK_AI_TIP_GROUPS.flat(), []);
  const isSearchMode = keyword.trim().length > 0;

  // 全局同义词映射（用户搜A也能匹配到B）
  const GLOBAL_SYNONYMS: Record<string, string[]> = {
    'ai生图': ['图片生成', 'AI画图', 'AI作图', '文生图', '图像生成', 'AI绘图', '画画', '生图'],
    '图片生成': ['AI生图', 'AI画图', 'AI作图', '文生图', '图像生成', 'AI绘图', '画画', '生图'],
    'ai文案': ['文案生成', '写文案', 'AI写作', '写标题', '写描述', '文案创作', '生成文案'],
    '文案生成': ['AI文案', 'AI写作', '写文案', '写标题', '写描述', '文案创作'],
    'ai视频': ['视频生成', 'AI做视频', '文生视频', 'AI剪辑', '视频创作'],
    '视频生成': ['AI视频', 'AI做视频', '文生视频', 'AI剪辑'],
    'ai配音': ['语音合成', 'AI语音', '文字转语音', 'TTS', 'AI旁白'],
    '语音合成': ['AI配音', '文字转语音', 'TTS', 'AI语音'],
    'ai数字人': ['数字人', '虚拟人', '数字员工', 'AI主播', '虚拟主播'],
    '数字人': ['AI数字人', '虚拟人', '数字员工', 'AI主播', '虚拟主播'],
    'ai编程': ['代码生成', '写代码', 'AI写代码', 'AI编程助手', '代码助手', '编程助手'],
    '代码生成': ['AI编程', '写代码', 'AI写代码', '代码助手'],
    'ai漫剧': ['漫画生成', 'AI漫画', '动漫生成', '短剧生成'],
    '智能体': ['AI智能体', 'Agent', 'Skill', '技能', '自动化', 'AI助理', '工作流'],
    'ai办公': ['办公自动化', 'AI办公', '效率工具', 'PPT生成', 'Excel助手'],
    'ai跨境': ['跨境AI', 'AI选品', 'AI运营', 'AI客服', '跨境助手'],
    'skill': ['智能体', '技能', 'Agent', '工作流'],
    'agent': ['智能体', '技能', 'Agent', '工作流'],
  };

   const filteredTips = useMemo(() => {
     const source = isSearchMode ? allTips : dailyTips;
     let tips: IAITip[] = [];
     if (isSearchMode) {
       const kw = keyword.trim().toLowerCase();
       const rawWords = keyword.trim().split(/[\s,，]+/).filter(w => w.length >= 2);
       // 同义词精确匹配（完全相等才扩展，避免误扩展）
       const expandedKws = new Set<string>([kw]);
       for (const [key, syns] of Object.entries(GLOBAL_SYNONYMS)) {
         if (kw === key) {
           syns.forEach(s => expandedKws.add(s.toLowerCase()));
         }
       }
       const kwList = Array.from(expandedKws);

       tips = source.filter(tip => {
         const titleLower = tip.title.toLowerCase();
         const catLower = tip.category.toLowerCase();
         const toolLower = tip.tool.toLowerCase();
         const tipsLower = tip.tips.toLowerCase();
         const pitLower = tip.pitfalls.toLowerCase();
         const stepsArr = Array.isArray(tip.steps) ? tip.steps : [];
         const stepsLower = stepsArr.map(s => String(s).toLowerCase()).join(' ');
         const tipSynsArr = (tip as any).synonyms;
         const tipSyns = Array.isArray(tipSynsArr) ? tipSynsArr.map(s => String(s).toLowerCase()).join(' ') : '';
         const plainLower = ((tip as any).plainLanguage as string | undefined)?.toLowerCase() || '';

         let strongHit = false;
         let score = 0;

         // 强字段：标题/分类/工具/同义词
         if (titleLower.includes(kw)) { score += 100; strongHit = true; }
         if (catLower === kw || catLower.includes(kw) || kw.includes(catLower)) { score += 60; strongHit = true; }
         if (toolLower.includes(kw)) { score += 50; strongHit = true; }
         if (tipSyns && kwList.some(k => tipSyns.includes(k))) { score += 55; strongHit = true; }

         // 正文类：步骤/技巧/避坑/大白话，统计命中次数
         let bodyHitCount = 0;
         for (const k of kwList) {
           if (k.length < 2) continue;
           if (stepsLower.includes(k)) bodyHitCount++;
           if (tipsLower.includes(k)) bodyHitCount++;
           if (pitLower.includes(k)) bodyHitCount++;
           if (plainLower.includes(k)) bodyHitCount++;
         }
         if (bodyHitCount >= 2) {
           score += bodyHitCount * 12;
           if (bodyHitCount >= 3) strongHit = true;
         }

         // 多关键词AND：必须每个词都出现在任意字段，且至少一个词在强字段
         if (rawWords.length > 1) {
           let allHit = true;
           let anyStrong = false;
           for (const w of rawWords) {
             const wl = w.toLowerCase();
             const inStrong = titleLower.includes(wl) || catLower.includes(wl) || toolLower.includes(wl) || tipSyns.includes(wl);
             const inBody = stepsLower.includes(wl) || tipsLower.includes(wl) || pitLower.includes(wl) || plainLower.includes(wl);
             if (!inStrong && !inBody) { allHit = false; break; }
             if (inStrong) anyStrong = true;
           }
           if (!allHit || !anyStrong) return false;
         } else if (!strongHit) {
           // 单关键词必须命中强字段或正文≥2次命中
           return false;
         }

         // 分类过滤
         if (activeCat !== '全部' && tip.category !== activeCat) return false;
         return score > 0;
       });
     } else {
       // 非搜索模式：按 activeCat 过滤
       tips = activeCat === '全部'
         ? source.slice()
         : source.filter(t => t.category === activeCat);
     }
     // 搜索模式下混合笔记
     if (isSearchMode) {
       const kw = keyword.trim().toLowerCase();
        const matchedNotes = aiNotes.filter(n =>
          (n.content || '').toLowerCase().includes(kw) ||
          (n.source || '').toLowerCase().includes(kw) ||
          (n.tags && n.tags.some(t => (t || '').toLowerCase().includes(kw)))
        );
       return { tips, notes: matchedNotes };
     }
     return { tips, notes: [] };
   }, [dailyTips, allTips, activeCat, keyword, isSearchMode, aiNotes]);

  const categoryCount = useMemo(() => {
    // 计数基于「当前展示集合的全分类分布」，"全部"显示总数
    const source = filteredTips.tips;
    const count: Record<string, number> = {};
    source.forEach(t => {
      count[t.category] = (count[t.category] || 0) + 1;
    });
    count['全部'] = source.length;
    return count;
  }, [filteredTips]);

  return (
    <div className="space-y-3">
      {/* Header（渐变 Hero 卡，折叠态只显示标题 + 摘要） */}
      <CollapsibleSection
        title="AI技巧本"
        subtitle="AI PLAYBOOK"
        summary={`${formatDateCN(today)} 更新 · 每天 ${dailyTips.length} 条干货`}
        badge={`${dailyTips.length} 条/天`}
        badgeColor="info"
        theme={theme}
        expanded={expandedId === 'hero'}
        onToggle={() => toggleSection('hero')}
        icon={<Sparkles className="size-5" />}
      >
        <div
          className="-mx-6 -mb-6 p-6 text-white"
          style={{
            background: `linear-gradient(135deg, ${theme.primary}, ${theme.primaryLight})`,
          }}
        >
          <div className="flex items-start gap-3">
            <div className="size-10 rounded-xl bg-white/15 backdrop-blur flex items-center justify-center shrink-0">
              <Sparkles className="size-5" />
            </div>
            <div className="space-y-1 flex-1 min-w-0">
              <div className="page-title-kicker opacity-80">AI PLAYBOOK</div>
              <h1 className="page-title-main">AI技巧本</h1>
              <p className="page-title-sub flex items-center gap-1">
                <Calendar className="size-3" />
                {formatDateCN(today)} 更新 · 每天 {dailyTips.length} 条干货
              </p>
            </div>
          </div>
          <div className="mt-4 pt-4 border-t border-white/15 text-sm opacity-90 leading-relaxed">
            AI文案 · AI生图 · AI视频 · AI配音 · AI数字人 · AI编程 · AI漫剧 · AI办公 · AI跨境
          </div>
        </div>
      </CollapsibleSection>

       {/* 页内锚点快捷导航 */}
       <div className="flex items-center gap-1 rounded-lg p-1 overflow-x-auto" style={{ backgroundColor: theme.ui.badgeBg || `${theme.primary}08` }}>
         {[
           { key: 'manju', label: 'AI漫剧全路径', icon: Video },
           { key: 'tips', label: 'AI技巧库', icon: Lightbulb },
           { key: 'notes', label: '我的笔记', icon: NotebookPen },
         ].map(item => {
           const Icon = item.icon;
           return (
             <button
               key={item.key}
               onClick={() => scrollToAnchor(item.key)}
               className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium whitespace-nowrap transition-all duration-200 ${
                 activeAnchor === item.key ? 'shadow-sm' : 'opacity-70 hover:opacity-100'
               }`}
               style={{
                 backgroundColor: activeAnchor === item.key ? theme.primary : 'transparent',
                 color: activeAnchor === item.key ? '#fff' : theme.primaryDark,
               }}
             >
               <Icon className="size-3.5" />
               {item.label}
             </button>
           );
         })}
       </div>

       {/* AI漫剧制作全路径 - 重点推荐 */}
       <section ref={el => { anchorRefs.current.manju = el; }} id="ai-manju-section">
        <CollapsibleSection
          className="accent-block-bg"
          title={AI_MANJU_FEATURED.title}
          subtitle={AI_MANJU_FEATURED.subtitle}
          summary={`${AI_MANJU_FEATURED.steps.length} 步全流程拆解 · 含贯穿示例与每步要点`}
          badge="⭐ 重点推荐"
          badgeColor="info"
          theme={theme}
          expanded={expandedId === 'manju'}
          onToggle={() => toggleSection('manju')}
          icon={<Video className="size-5" />}
        >
          {'exampleSetting' in AI_MANJU_FEATURED && AI_MANJU_FEATURED.exampleSetting && (
            <div
              className="mb-4 p-3 rounded-lg text-xs leading-relaxed border-l-2"
              style={{
                backgroundColor: `${theme.primary}08`,
                borderColor: theme.primary,
                color: theme.primary,
              }}
            >
              <span className="font-semibold">📖 贯穿示例：</span>
              {AI_MANJU_FEATURED.exampleSetting}
            </div>
          )}
          <div className="space-y-2">
             {AI_MANJU_FEATURED.steps.map((step, idx) => {
               const isOpen = manjuExpandedStep === idx;
               return (
                 <div
                   key={idx}
                   className="rounded-xl border overflow-hidden transition-all duration-300"
                   style={{ borderColor: `${theme.primary}20` }}
                 >
                   <button
                     onClick={() => toggleManjuStep(idx)}
                     className="w-full flex items-start gap-3 p-4 text-left hover:bg-muted/30 transition-colors"
                   >
                     <div
                       className="size-7 rounded-full flex items-center justify-center text-white text-xs font-bold shrink-0 mt-0.5"
                       style={{ backgroundColor: theme.primary }}
                     >
                       {idx + 1}
                     </div>
                     <div className="flex-1 min-w-0">
                       <div className="flex items-center gap-2 flex-wrap">
                         <h3 className="font-semibold text-foreground text-sm">{step.title}</h3>
                         <Badge variant="outline" className="text-xs font-normal">
                           {step.tool}
                         </Badge>
                       </div>
                       <p className="text-xs text-muted-foreground mt-0.5 line-clamp-1">{step.desc}</p>
                     </div>
                     <ChevronDown
                       className={`size-4 text-muted-foreground shrink-0 mt-1 transition-transform duration-200 ${
                         isOpen ? 'rotate-180' : ''
                       }`}
                     />
                   </button>
                   <div className={`grid transition-all duration-300 ${isOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0'}`}
                        style={{ transitionTimingFunction: 'cubic-bezier(0.16, 1, 0.3, 1)' }}>
                     <div className="overflow-hidden">
                       <div className="px-4 pb-4 pt-1">
                         <ul className="space-y-1.5">
                           {step.keyPoints.map((kp, i) => (
                             <li key={i} className="text-sm text-foreground/80 flex items-start gap-2">
                               <ChevronRight className="size-3.5 shrink-0 mt-0.5" style={{ color: theme.primary }} />
                               <span>{kp}</span>
                             </li>
                           ))}
                         </ul>
                       </div>
                     </div>
                   </div>
                 </div>
               );
             })}
            </div>
        </CollapsibleSection>
       </section>

       {/* 分类 Tab + 技巧卡片 */}
       <section ref={el => { anchorRefs.current.tips = el; }} id="ai-tips-section">
        <CollapsibleSection
          title="AI技巧分类"
          subtitle="按分类浏览，或全局搜索整个技巧库"
          summary={
            isSearchMode
              ? `搜索：找到 ${filteredTips.tips.length + filteredTips.notes.length} 条结果`
              : `今日推荐 ${dailyTips.length} 条 · 共 ${allTips.length} 条轮换`
          }
          badge={`${allTips.length} 条`}
          badgeColor="info"
          theme={theme}
          expanded={expandedId === 'tips'}
          onToggle={() => toggleSection('tips')}
          icon={<Lightbulb className="size-5" />}
        >
          <div className="space-y-3">
            {/* 搜索框（原位于 CardHeader，移入展开区避免嵌入头部按钮） */}
            <div className="relative">
              <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                type="search"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                placeholder="搜索全部AI技巧（标题/分类/工具/内容/来源）"
                className="pl-9 pr-9 h-10 bg-muted/30"
              />
              {keyword && (
                <button
                  onClick={() => setKeyword('')}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground p-1 rounded-md hover:bg-muted"
                  aria-label="清除搜索"
                >
                  <X className="size-4" />
                </button>
              )}
            </div>
            {isSearchMode && (
              <div className="flex items-center justify-between text-xs text-muted-foreground px-1">
                <span>
                   搜索结果：找到 <span className="font-medium" style={{ color: theme.primary }}>{filteredTips.tips.length + filteredTips.notes.length}</span> 条 / 共 {allTips.length} 条
                </span>
                <button onClick={() => setKeyword('')} style={{ color: theme.primary }}>
                  清除搜索
                </button>
              </div>
            )}
            {!isSearchMode && (
              <div className="flex items-center gap-2 text-xs text-muted-foreground px-1">
                <Calendar className="size-3.5" />
                今日推荐 {dailyTips.length} 条 · 共 {allTips.length} 条轮换
              </div>
            )}
            <Tabs value={activeCat} onValueChange={v => setActiveCat(v as AITipCategory)}>
              <TabsList className="w-full flex flex-wrap h-auto gap-1 bg-muted/50 p-1">
                {AI_TIP_CATEGORIES.map(cat => {
                  const Icon = categoryIconMap[cat];
                  const count = cat === '全部' ? dailyTips.length : (categoryCount[cat] || 0);
                  return (
                    <TabsTrigger
                      key={cat}
                      value={cat}
                      className="flex items-center gap-1.5 data-[state=active]:bg-background data-[state=active]:shadow-sm text-xs px-3 py-1.5"
                    >
                      <Icon className="size-3.5" />
                      {cat}
                      <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-muted text-muted-foreground data-[state=active]:bg-primary/10 data-[state=active]:text-primary">
                        {count}
                      </span>
                    </TabsTrigger>
                  );
                })}
              </TabsList>

              <div className="mt-5 space-y-3">
                 {filteredTips.tips.length === 0 && filteredTips.notes.length === 0 ? (
                  <div className="text-center py-12 text-muted-foreground text-sm">
                    暂无该分类技巧
                  </div>
                 ) : (
                   <>
                     {/* 我的笔记（搜索模式优先展示） */}
                     {filteredTips.notes.length > 0 && (
                       <div className="space-y-3">
                         <div className="flex items-center gap-2 px-1">
                           <NotebookPen className="size-4" style={{ color: theme.primary }} />
                           <span className="text-xs font-semibold" style={{ color: theme.primary }}>
                             我的笔记 ({filteredTips.notes.length}条)
                           </span>
                         </div>
                         {filteredTips.notes.map(note => (
                           <Card
                             key={note.id}
                             className="border-0 shadow-sm overflow-hidden"
                             style={{
                               backgroundColor: theme.ui.glassBg,
                               backdropFilter: 'blur(10px)',
                               WebkitBackdropFilter: 'blur(10px)',
                               boxShadow: theme.ui.glassShadow,
                               border: `1px solid ${theme.ui.cardBorder}`,
                             }}
                           >
                             <CardContent className="p-4">
                               <div className="flex items-center gap-2 mb-2">
                                 <Badge
                                   className="text-[10px] border-0"
                                   style={{ backgroundColor: `${theme.primary}15`, color: theme.primary }}
                                 >
                                   {note.source}
                                 </Badge>
                                 <span className="text-[10px] text-muted-foreground">{note.date}</span>
                               </div>
                               <p className="text-sm whitespace-pre-wrap leading-relaxed text-foreground">
                                 {note.content}
                               </p>
                             </CardContent>
                           </Card>
                         ))}
                       </div>
                     )}

                     {/* AI技巧列表 */}
                     {filteredTips.tips.length > 0 && (
                       <div className="space-y-3">
                         {isSearchMode && (
                           <div className="flex items-center gap-2 px-1 pt-2">
                             <Sparkles className="size-4" style={{ color: theme.primary }} />
                             <span className="text-xs font-semibold" style={{ color: theme.primary }}>
                               AI技巧 ({filteredTips.tips.length}条)
                             </span>
                           </div>
                         )}
                         {filteredTips.tips.length > 0 && filteredTips.tips.map(tip => {
                   const colors = categoryColorMap[tip.category] || categoryColorMap['AI文案'];
                   const isExpanded = expandedTipId === tip.id;
                   return (
                     <div
                       key={tip.id}
                       className={`rounded-xl border transition-all cursor-pointer hover:shadow-sm ${colors.border}`}
                       onClick={() => setExpandedTipId(isExpanded ? null : tip.id)}
                     >
                       <div className={`p-4 ${colors.bg}/60`}>
                         <div className="flex items-start gap-3">
                           <div className={`size-9 rounded-lg flex items-center justify-center shrink-0 ${colors.bg} ${colors.border} border`}>
                             {(() => {
                               const Icon = categoryIconMap[tip.category as AITipCategory] || Lightbulb;
                               return <Icon className={`size-4.5 ${colors.text}`} />;
                             })()}
                           </div>
                           <div className="flex-1 min-w-0">
                             <div className="flex items-center gap-2 flex-wrap">
                               <h3 className="subsection-title text-primary-strong">{tip.title}</h3>
                               <Badge variant="outline" className={`text-[10px] font-normal ${colors.text} ${colors.border} ${colors.bg}`}>
                                 {tip.category}
                               </Badge>
                             </div>
                              <p className="text-xs text-tertiary-strong mt-1">
                                 🛠 工具：{tip.tool}
                               </p>
                              <p className="text-xs text-secondary-strong mt-0.5">
                                 📺 来源：{tip.source.platform}@{tip.source.account}
                               </p>
                           </div>
                           <ChevronRight
                             className={`size-4 text-muted-foreground shrink-0 transition-transform ${
                               isExpanded ? 'rotate-90' : ''
                             }`}
                           />
                         </div>
                       </div>

                       <div className={`collapse-grid ${isExpanded ? 'collapse-expanded' : 'collapse-collapsed'}`}>
                          <div className="collapse-inner">
                          <div className="px-4 pb-4 space-y-3 border-t border-border/50">
                            {/* 操作步骤 */}
                            <div className="pt-3">
                              <h4 className="text-xs font-semibold text-foreground flex items-center gap-1.5 mb-2">
                                <ListChecks className="size-3.5" style={{ color: theme.primary }} />
                                操作步骤
                              </h4>
                              <ol className="space-y-1.5">
                                {ensureArray(tip.steps).map((step, i) => (
                                  <li key={i} className="text-sm text-foreground/80 flex items-start gap-2">
                                    <span
                                      className="size-4 rounded-full flex items-center justify-center text-[10px] font-bold text-white shrink-0 mt-0.5 tabular-nums"
                                      style={{ backgroundColor: theme.primary }}
                                    >
                                      {i + 1}
                                    </span>
                                    <span>{step}</span>
                                  </li>
                                ))}
                              </ol>
                            </div>

                            {/* 技巧要点 */}
                            <div>
                              <h4 className="text-xs font-semibold text-foreground flex items-center gap-1.5 mb-1.5">
                                <Lightbulb className="size-3.5 text-amber-500" />
                                技巧要点
                              </h4>
                               <div className="bg-amber-50/50 rounded-lg px-3 py-2 border border-amber-100">
                                 <RichTipText
                                   text={tip.tips}
                                   className="text-foreground/80 text-xs"
                                   accentColor="#d97706"
                                 />
                               </div>
                            </div>

                            {/* 避坑提醒 */}
                            <div>
                              <h4 className="text-xs font-semibold text-foreground flex items-center gap-1.5 mb-1.5">
                                <AlertTriangle className="size-3.5 text-red-500" />
                                避坑提醒
                              </h4>
                               <div className="bg-red-50/50 rounded-lg px-3 py-2 border border-red-100">
                                 <RichTipText
                                   text={tip.pitfalls}
                                   className="text-foreground/80 text-xs"
                                   accentColor="#dc2626"
                                 />
                               </div>
                            </div>
                          </div>
                          </div>
                        </div>
                          </div>
                        ); 
                      })}
                     </div>
                     )}
                   </>
                 )}
              </div>
            </Tabs>
          </div>
        </CollapsibleSection>
       </section>

       {/* 我的AI技巧笔记 */}
       <section ref={el => { anchorRefs.current.notes = el; }} id="ai-notes-section">
        <CollapsibleSection
          title="我的AI技巧笔记"
          subtitle="记录心得、prompt 与独门技巧"
          summary="支持标签与本地保存，笔记内容可被全局搜索命中"
          badge="本地保存"
          badgeColor="default"
          theme={theme}
          expanded={expandedId === 'notes'}
          onToggle={() => toggleSection('notes')}
          icon={<NotebookPen className="size-5" />}
        >
          <NotePadSection
            storageKey="note:ai-tips"
            title="我的AI技巧笔记"
            icon={<NotebookPen className="size-4" />}
            theme={theme}
             placeholder="记录AI使用心得、常用prompt、独门技巧..."
             onNotesChange={setAiNotes}
           />

        </CollapsibleSection>
       </section>
      </div>
  );
}
